{
  "name": "dsh-agent-switcher",
  "version": "0.5.0",
  "description": "Create, manage, and switch your own DeepSeek Harness agents: per-agent settings, history, search and pinning, a try-it playground, and a custom_agent tool for model-authored subagents.",
  "type": "module",
  "main": "lib/index.js",
  "exports": {
    ".": "./lib/index.js",
    "./client": "./lib/client.js",
    "./package.json": "./package.json",
    "./locale/*.json": "./locale/*.json",
    "./icon": "./icon.svg"
  },
  "dsh": {
    "bundle": {
      "patch": "./cordis.patch.yml"
    },
    "client": {
      "inject": [],
      "platform": "web"
    }
  },
  "dependencies": {
    "js-yaml": "^4.3.2"
  },
  "files": [
    "lib",
    "locale/*.json",
    "icon.svg",
    "cordis.patch.yml",
    "README.md",
    "CHANGELOG.md",
    "LICENSE"
  ],
  "icon": "icon.svg",
  "engines": {
    "node": ">=22"
  },
  "keywords": [
    "dsh",
    "deepseek-harness",
    "dsh-plugin",
    "agent",
    "preset",
    "subagent",
    "settings",
    "history",
    "opencode"
  ],
  "author": "w4ua",
  "license": "MIT"
}
